import java.util.*;class Solution{public List<List<Integer>> zigzagLevelOrder(TreeNode r){List<List<Integer>>o=new ArrayList<>();if(r==null)return o;Queue<TreeNode>q=new ArrayDeque<>();q.add(r);boolean rev=false;while(!q.isEmpty()){int n=q.size();Integer[]v=new Integer[n];for(int i=0;i<n;i++){TreeNode x=q.remove();v[rev?n-1-i:i]=x.val;if(x.left!=null)q.add(x.left);if(x.right!=null)q.add(x.right);}o.add(Arrays.asList(v));rev=!rev;}return o;}}
